#include <string.h>
#include <stdio.h>

typedef long long int ll;

ll scan(){ll x; scanf("%lld",&x); return x;}

void merge (ll *a, ll n, ll m) {
    ll i, j, k;
    ll x[n];
    for (i = 0, j = m, k = 0; k < n; k++) {
        x[k] = j == n      ? a[i++]
        : i == m      ? a[j++]
        : a[j] < a[i] ? a[j++]
        :               a[i++];
    }
    for (i = 0; i < n; i++) {
        a[i] = x[i];
    }
}

void merge_sort (ll *a, ll n) {
    if (n < 2)
        return;
    ll m = n / 2;
    merge_sort(a, m);
    merge_sort(a + m, n - m);
    merge(a, n, m);
}

int main(int argc, const char * argv[]) {


    ll N;
    N = scan();
    ll V[N-1];
    ll me = 0;
    ll T = 0;

    for (int i = 0; i<N; i++) {
        V[i] = 0;
    }

    for (ll a = 0; a<N; a++) {
        ll X;
        scanf("%lld",&X);

        if (a == 0) me = X;
        else V[a] = X;

    }

    merge_sort(V, N-1);

    while (me <= V[N-1]) {
        V[N-1] --;
        me ++;
        T --;
        merge_sort(V, N);
    }

    printf("%lld",-T);


    return 0;
}

